begin;

select set_config('hadith.lifecycle_author', 'Bahri', true);
select set_config('hadith.lifecycle_justification', U&'Publication valid\\00e9e des 42 hadiths d''An-Nawawi', true);
select set_config('hadith.lifecycle_evidence', 'PDF fr-40-hadiths.pdf, traduction Rachid Maach, mention Libre de droits, URL Supabase Storage fr/fr-40-hadiths.pdf, SHA-256 3D36EB9BE1657C0D8FC683D34DDC73DB450800AE91B9EEFB2746D0FF12C0E90D', true);
select set_config('hadith.lifecycle_version', 'fawazahmed0-hadith-api@1:nawawi:ara+fra', true);

do $$
declare n integer;
begin
 select count(*) into n from public.hadiths h join public.hadith_collections c on c.id=h.collection_id where h.source_version_id='c2b5310f-3601-46c4-a2d8-3916895ba1d2' and c.slug='nawawi' and h.source_hadith_id like 'nawawi:%';
 if n<>42 then raise exception 'Expected 42 Nawawi hadiths, got %',n; end if;
 select count(*) into n from public.hadith_translations t join public.hadiths h on h.id=t.hadith_id join public.hadith_collections c on c.id=h.collection_id where t.source_version_id='c2b5310f-3601-46c4-a2d8-3916895ba1d2' and t.language_code='fr' and c.slug='nawawi' and h.source_hadith_id like 'nawawi:%';
 if n<>42 then raise exception 'Expected 42 Nawawi translations, got %',n; end if;
end $$;

update public.hadith_sources s set status=U&'Valid\00e9e' where s.id=(select source_id from public.hadith_source_versions where id='c2b5310f-3601-46c4-a2d8-3916895ba1d2');

do $$
declare parent_status text;
begin
 select s.status into parent_status from public.hadith_source_versions v join public.hadith_sources s on s.id=v.source_id where v.id='c2b5310f-3601-46c4-a2d8-3916895ba1d2';
 if parent_status is distinct from U&'Valid\00e9e' then raise exception 'Nawawi parent source is not validated'; end if;
end $$;

update public.hadith_source_versions set edition='2021',license='Libre de droits',attribution=U&'D\00e9couverte de l''islam \2014 traduction Rachid Maach, 1\00e8re \00e9dition 2021',source_url='fr/fr-40-hadiths.pdf' where id='c2b5310f-3601-46c4-a2d8-3916895ba1d2';

insert into public.hadith_source_legal_reviews(source_version_id,decision,redistribution_allowed,license_identifier,license_evidence_reference,attribution_snapshot,terms_url_snapshot,source_url_snapshot,metadata_fingerprint,reviewed_by,justification)
select v.id,'approved',true,v.license,U&'fr-40-hadiths.pdf\000aTraduction : Rachid Maach\000aD\00e9couverte de l''islam\000a1\00e8re \00e9dition : 2021\000aMention : \00ab Libre de droits \00bb',v.attribution,v.terms_url,v.source_url,public.hadith_source_version_legal_fingerprint(v.id),'Bahri','Validation de la traduction fran?aise officielle Nawawi ? partir du PDF fourni.' from public.hadith_source_versions v where v.id='c2b5310f-3601-46c4-a2d8-3916895ba1d2' and not exists(select 1 from public.hadith_source_legal_reviews r where r.source_version_id=v.id and r.decision='approved');

do $$
declare review_count integer;
begin
 select count(*) into review_count from public.hadith_source_legal_reviews r join public.hadith_source_versions v on v.id=r.source_version_id
 where r.source_version_id='c2b5310f-3601-46c4-a2d8-3916895ba1d2' and r.decision='approved' and r.reviewed_by='Bahri'
   and r.license_identifier=v.license and r.attribution_snapshot=v.attribution and r.source_url_snapshot=v.source_url
   and r.metadata_fingerprint=public.hadith_source_version_legal_fingerprint(v.id);
 if review_count<>1 then raise exception 'Nawawi legal review does not match current source metadata'; end if;
end $$;

update public.hadith_translations t set translation_text=p.translation_text,translator='Rachid Maach',source_name=U&'D\00e9couverte de l''islam',source_url='fr/fr-40-hadiths.pdf',license='Libre de droits',attribution=U&'D\00e9couverte de l''islam \2014 traduction Rachid Maach, 1\00e8re \00e9dition 2021',verification_status='verified' from (values
    (U&'nawawi:1', U&'Le prince des croyants, Abou Hafs, \2018Oumar ibn Al-Khatt\00e2b \f074 rapporte avoir entendu le Messager d\2019Allah \f072 dire : \00ab Les actes ne valent que par leurs intentions et chacun sera r\00e9compens\00e9 selon son intention. Quiconque aura \00e9migr\00e9 pour Allah et Son Messager obtiendra ce pour quoi il aura \00e9migr\00e9 et quiconque aura \00e9migr\00e9 dans un but purement terrestre ou pour \00e9pouser une femme obtiendra ce pour quoi il aura \00e9migr\00e9. \00bb [Rapport\00e9 par les deux savants du hadith de r\00e9f\00e9rence : Abou \2018Abdillah Mouhammad ibn Ism\00e2\2019\00eel ibn Ibr\00e2h\00eem ibn Al-Mough\00eerah ibn Bardizbah Al-Jou\2019fi Al-Boukh\00e2ri et Abou Al-Housayn Mouslim ibn Al-Hajj\00e2j ibn Mouslim Al-Qouchayri An- Nays\00e2bouri, dans leurs recueils authentiques qui sont les livres les plus authentiques jamais compos\00e9s par les hommes] L\2019islam, la foi et l\2019excellence'),
    (U&'nawawi:2', U&'\2018Oumar \f074 toujours relate ce qui suit : \00ab Alors que nous \00e9tions un jour assis en compagnie du Messager d\2019Allah \f072 se pr\00e9senta \00e0 nous un homme portant des v\00eatements extr\00eamement blancs, les cheveux tr\00e8s noirs, et ne pr\00e9sentant aucune trace de voyage. Pourtant, aucun d\2019entre nous ne le connaissait. Il s\2019assit pr\00e8s du Proph\00e8te ses genoux contre ceux du Messager d\2019Allah et la paume de ses mains sur ses cuisses, puis il dit : \00ab Mouhammad ! \00ab Parle-moi de l\2019islam. \00bb Il r\00e9pondit : \00ab L\2019islam consiste \00e0 t\00e9moigner qu\2019il n\2019y a de divinit\00e9 en droit d\2019\00eatre ador\00e9e qu\2019Allah et que Mouhammad est le Messager d\2019Allah, \00e0 accomplir la pri\00e8re rituelle, \00e0 s\2019acquitter de l\2019aum\00f4ne l\00e9gale, \00e0 je\00fbner le mois de Ramadan et \00e0 accomplir le p\00e8lerinage au Sanctuaire pour celui qui en a les moyens. \00bb L\2019homme dit : \00ab Tu dis vrai. \00bb Nous f\00fbmes surpris de son acquiescement, car c\2019est lui qui avait pos\00e9 la question. L\2019homme poursuivit : \00ab Parle-moi de la foi. \00bb Il dit : \00ab Il s\2019agit de croire en Allah, Ses anges, Ses Livres, Ses Messagers, au Jour dernier et de croire au destin, que ses cons\00e9quences soient favorables ou d\00e9favorables. \00bb Il dit : \00ab Tu dis vrai. \00bb L\2019homme ajouta : \00ab Parle-moi de l\2019excellence. \00bb Il r\00e9pondit : \00ab C\2019est le fait d\2019adorer Allah comme si tu Le voyais, car si toi tu ne Le vois pas, Lui te voit. \00bb Il ajouta : \00ab Parle-moi de l\2019Heure. \00bb Il r\00e9pondit : \00ab Celui qui est interrog\00e9 n\2019en est pas mieux inform\00e9 que celui qui pose la question. \00bb L\2019homme poursuivit : \00ab Indique-moi ses signes pr\00e9curseurs. \00bb Il dit : \00ab Lorsque l\2019esclave donnera naissance \00e0 sa ma\00eetresse, et que tu verras les va-nu-pieds, d\00e9nud\00e9s, sans le sou, gardiens de moutons, rivaliser dans la hauteur des constructions. \00bb Puis il s\2019en alla et je restai ainsi un certain temps. Le Messager d\2019Allah me dit alors : \00ab \2018Oumar ! Sais-tu qui m\2019a interrog\00e9 ? \00bb Je r\00e9pondis : \00ab Allah et Son Messager le savent mieux que quiconque. \00bb \00ab C\2019est Gabriel, venu vous enseigner votre religion \00bb, r\00e9pondit le Proph\00e8te. [Mouslim] Les cinq piliers de l\2019islam'),
    (U&'nawawi:3', U&'Abou \2018Abd Ar-Rahm\00e2n \2018Abdoullah ibn \2018Oumar ibn Al- Khatt\00e2b \f074 rapporte avoir entendu le Messager d\2019Allah \f072 dire : \00ab L\2019islam repose sur cinq piliers : le t\00e9moignage qu\2019il n\2019y a de divinit\00e9 en droit d\2019\00eatre ador\00e9e qu\2019Allah et que Mouhammad est le Messager d\2019Allah, l\2019accomplissement de la pri\00e8re, le versement de l\2019aum\00f4ne l\00e9gale, le p\00e8lerinage \00e0 la Mecque et le je\00fbne du mois de Ramadan. \00bb1 [Al-Boukh\00e2ri et Mouslim] La pr\00e9destination'),
    (U&'nawawi:4', U&'Abou \2018Abd Ar-Rahm\00e2n \2018Abdoullah ibn Mas\2019oud \f074 a dit : Le Messager d\2019Allah \f072, l\2019homme v\00e9ridique et digne de foi, nous a affirm\00e9 : \00ab Chacun de vous se forme dans le ventre de sa m\00e8re durant quarante jours d\2019abord sous forme d\2019une quantit\00e9 insignifiante de sperme. Il devient 1 De ce hadith sont tir\00e9s les cinq piliers de l\2019islam : la profession de foi, proclamation de l\2019unicit\00e9 d\2019Allah et croyance en la mission de Mouhammad, la pri\00e8re rituelle que le musulman accomplit cinq fois par jour en direction de la Mecque, la Zakat, ou d\00eeme, que le croyant est tenu de verser une fois dans l\2019ann\00e9e aux pauvres notamment, le je\00fbne du mois de Ramadan et le p\00e8lerinage \00e0 la Mecque pour celui qui en a les moyens physiques et mat\00e9riels. ensuite un corps s\2019accrochant \00e0 la matrice2 pour une p\00e9riode identique, puis une masse de chair3 pour une p\00e9riode similaire. C\2019est alors que l\2019ange lui est envoy\00e9 pour insuffler en lui la vie et avec ordre d\2019\00e9crire quatre choses : sa subsistance, la dur\00e9e de sa vie, ses \0153uvres et s\2019il sera parmi les damn\00e9s ou les bienheureux. Par Allah, en dehors de qui il n\2019y pas de divinit\00e9 en droit d\2019\00eatre ador\00e9e, il se peut que l\2019un d\2019entre vous accomplisse4 les \0153uvres des \00e9lus du Paradis au point d\2019en \00eatre s\00e9par\00e9 d\2019une simple coud\00e9e. Il est alors rattrap\00e9 par son destin et commet les actes des damn\00e9s de l\2019Enfer o\00f9 il entrera. De m\00eame, il se peut que l\2019un d\2019entre vous commette les actes des damn\00e9s de l\2019Enfer au point d\2019en \00eatre s\00e9par\00e9 d\2019une simple coud\00e9e. Il est alors rattrap\00e9 par son destin et accomplit les \0153uvres des \00e9lus du Paradis o\00f9 il entrera. \00bb [Al-Boukh\00e2ri et Mouslim] Les inventions dans la religion'),
    (U&'nawawi:5', U&'Selon la m\00e8re des croyants, Oumm \2018Abdillah \2018\00c2\00efchah, qu\2019Allah l\2019agr\00e9e, le Messager d\2019Allah \f072 a dit : \00ab Quiconque 2 Il peut s\2019agir de l\2019\0153uf qui, comme l\2019a \00e9tabli la m\00e9decine moderne, \00ab s\2019accroche \00bb dans l\2019ut\00e9rus lors de la nidation au moyen de villosit\00e9s. Pr\00e9cisons toutefois que la plupart des commentateurs parlent d\2019un \00ab caillot de sang \00bb. 3 L\2019embryon. Litt\00e9ralement : une bouch\00e9e de chair ou de la chair m\00e2ch\00e9e. 4 Aux yeux des gens, pr\00e9cisent certains commentateurs. introduit dans notre religion ce qui lui est \00e9tranger verra son acte rejet\00e9. \00bb [Al-Boukh\00e2ri et Mouslim] Selon une autre version de Mouslim : \00ab Quiconque accomplit un acte qui n\2019est pas conforme \00e0 notre religion verra son acte rejet\00e9. \00bb Le scrupule'),
    (U&'nawawi:6', U&'Abou \2018Abdillah An-Nou\2019m\00e2n ibn Bach\00eer \f074 rapporte avoir entendu le Messager d\2019Allah \f072 dire : \00ab Le licite est clair et l\2019illicite l\2019est \00e9galement, mais \00e0 la fronti\00e8re entre le licite et l\2019illicite se trouvent des choses douteuses que peu de gens connaissent. Quiconque renonce \00e0 ce qui est douteux a pr\00e9serv\00e9 sa religion et son honneur. Mais celui qui commet des choses douteuses tombera n\00e9cessairement dans le p\00e9ch\00e9, tel le berger qui fait pa\00eetre ses b\00eates \00e0 proximit\00e9 d\2019un domaine priv\00e9 o\00f9 ils risquent \00e0 tout moment de brouter. Or, chaque souverain poss\00e8de un domaine r\00e9serv\00e9, et le domaine r\00e9serv\00e9 d\2019Allah est ce qu\2019il a prohib\00e9. Sachez \00e9galement qu\2019il y a dans le corps un morceau de chair qui, s\2019il est vertueux, rendra le corps entier vertueux et s\2019il est corrompu, corrompra le corps tout entier. Ce morceau de chair est le c\0153ur. \00bb [Al- Boukh\00e2ri et Mouslim] La sinc\00e9rit\00e9'),
    (U&'nawawi:7', U&'Selon Abou Rouqayyah Tam\00eem ibn Aws Ad-D\00e2ri \f074, le Proph\00e8te \f072 a dit : \00ab La religion repose sur la sinc\00e9rit\00e9. \00bb Nous avons dit : \00ab Envers qui ? \00bb Il r\00e9pondit : \00ab Envers Allah, envers Son Livre, envers Son Messager et envers le chef et le commun des musulmans. \00bb [Mouslim] La sacralit\00e9 des biens du musulman'),
    (U&'nawawi:8', U&'D\2019apr\00e8s Ibn \2018Oumar \f074, le Messager d\2019Allah \f072 a dit : \00ab J\2019ai re\00e7u l\2019ordre de combattre les gens jusqu\2019\00e0 ce qu\2019ils t\00e9moignent qu\2019il n\2019y a de divinit\00e9 en droit d\2019\00eatre ador\00e9e qu\2019Allah et que Mouhammad est le Messager d\2019Allah, qu\2019ils accomplissent la pri\00e8re et s\2019acquittent de l\2019aum\00f4ne l\00e9gale. S\2019ils font cela, ils pr\00e9serveront leur personne et leurs biens, sauf dans ce que l\2019islam impose et c\2019est \00e0 Allah le Tr\00e8s Haut qu\2019ils devront rendre des comptes. \00bb [Al-Boukh\00e2ri et Mouslim] Ob\00e9ir sans multiplier les questions'),
    (U&'nawawi:9', U&'Abou Hourayrah \2018Abd Ar-Rahm\00e2n ibn Sakhr \f074 rapporte avoir entendu le Messager d\2019Allah \f072 dire : \00ab Si je vous interdis une chose, \00e9cartez-vous-en, et si je vous donne un ordre, ex\00e9cutez-le dans la mesure du possible. En effet, les nations qui ont v\00e9cu avant vous ne furent perdues que pour avoir accabl\00e9 leurs proph\00e8tes de questions et s\2019\00eatre oppos\00e9es \00e0 ces derniers. \00bb [Al-Boukh\00e2ri et Mouslim] Allah n\2019accepte que ce qui est pur'),
    (U&'nawawi:10', U&'Selon Abou Hourayrah \f074, le Messager d\2019Allah \f072 a dit : \00ab Allah le Tr\00e8s Haut est pur et n\2019accepte que ce qui est pur. Et Allah a ordonn\00e9 aux croyants ce qu\2019Il a ordonn\00e9 aux Messagers. Le Tr\00e8s Haut a dit : \201cMessagers ! Choisissez les nourritures les plus pures et accomplissez les \0153uvres les plus vertueuses\201d. Et Il a dit : \201cVous qui croyez ! Nourrissez-vous des aliments purs et sains que Nous vous avons attribu\00e9s\201d. \00bb Puis il mentionna l\2019homme qui voyage longuement, les cheveux \00e9bouriff\00e9s, le visage couvert de poussi\00e8re et qui tend les mains vers le ciel en disant : \00ab Seigneur ! Seigneur \00bb, alors que sa nourriture a \00e9t\00e9 acquise de mani\00e8re illicite, de m\00eame que sa boisson et ses v\00eatements, et qu\2019il a \00e9t\00e9 nourri de biens illicites. Comment pourrait-il \00eatre exauc\00e9 ? [Mouslim] Renoncer \00e0 ce qui est douteux'),
    (U&'nawawi:11', U&'Abou Mouhammad Al-Hasan, fils de \2018Ali ibn Abi T\00e2lib, petit-fils et bien-aim\00e9 du Messager d\2019Allah \f072, a dit : J\2019ai retenu ces paroles du Messager d\2019Allah \f072 : \00ab Renonce \00e0 ce qui suscite en toi des doutes pour ce qui n\2019en suscite pas. \00bb [An-Nas\00e2\00ef et At-Tirmidhi qui pr\00e9cise : \00ab hadith hasan sah\00eeh \00bb] Se m\00ealer de ce qui nous regarde'),
    (U&'nawawi:12', U&'D\2019apr\00e8s Abou Hourayrah \f074, le Messager d\2019Allah \f072 a dit : \00ab Le bon musulman ne se m\00eale jamais de ce qui ne le regarde pas. \00bb [Hadith authentique (hasan), rapport\00e9 notamment par At-Tirmidhi en ces termes] Vouloir le bien aux autres'),
    (U&'nawawi:13', U&'D\2019apr\00e8s Abou Hamzah Anas ibn M\00e2lik \f074 - le serviteur du Messager d\2019Allah - le Proph\00e8te \f072 a dit : \00ab Nul d\2019entre vous n\2019aura v\00e9ritablement la foi tant qu\2019il n\2019aimera pas pour son fr\00e8re croyant ce qu\2019il aime pour lui-m\00eame. \00bb5 [Al- Boukh\00e2ri et Mouslim] La sacralit\00e9 de la vie du musulman'),
    (U&'nawawi:14', U&'Selon Ibn Mas\2019oud \f074, le Messager d\2019Allah \f072 a dit : \00ab Il n\2019est permis de verser le sang du musulman que dans trois cas : en cas de fornication, pour celui qui a d\00e9j\00e0 \00e9t\00e9 mari\00e9, en application de la loi du talion et en cas d\2019apostasie, pour celui qui rompt avec les musulmans. \00bb [Al-Boukh\00e2ri et Mouslim] 5 Cette charit\00e9 musulmane repr\00e9sente sans doute le plus haut degr\00e9 de la foi, comme l\2019indiquent les paroles du Proph\00e8te : \00ab n\2019aura v\00e9ritablement la foi \00bb, de m\00eame que la charit\00e9 chr\00e9tienne constitue la plus grande des trois vertus th\00e9ologales. Ces paroles du Proph\00e8te \f072 semblent d\2019un autre temps \00e0 une \00e9poque o\00f9 l\2019individualisme et l\2019\00e9go\00efsme sont devenus la r\00e8gle. Honorer l\2019h\00f4te et le voisin'),
    (U&'nawawi:15', U&'Selon Abou Hourayrah \f074, le Messager d\2019Allah \f072 a dit : \00ab Que celui qui croit en Allah et au Jour dernier dise du bien ou se taise. Que celui qui croit en Allah et au Jour dernier honore son voisin. Que celui qui croit en Allah et au Jour dernier honore son h\00f4te. \00bb [Al-Boukh\00e2ri et Mouslim] Contenir sa col\00e8re'),
    (U&'nawawi:16', U&'D\2019apr\00e8s Abou Hourayrah \f074, un homme dit au Proph\00e8te \f072 : \00ab Fais-moi une recommandation. \00bb Il dit : \00ab Ne te mets pas en col\00e8re. \00bb L\2019homme r\00e9it\00e9ra sa demande, obtenant \00e0 chaque fois la m\00eame r\00e9ponse : \00ab Ne te mets pas en col\00e8re. \00bb [Al-Boukh\00e2ri] La bont\00e9 envers les hommes et les animaux'),
    (U&'nawawi:17', U&'D\2019apr\00e8s Abou Ya\2019l\00e2 Chadd\00e2d ibn Aws \f074, le Messager d\2019Allah \f072 a dit : \00ab Allah a prescrit la bont\00e9 en toute chose. Aussi, lorsque vous devez ex\00e9cuter quelqu\2019un, faites-le convenablement et lorsque vous devez \00e9gorger une b\00eate, faites-le convenablement. Aiguisez le couteau et soulagez l\2019animal. \00bb [Mouslim] Craindre Allah et bien se comporter avec les gens'),
    (U&'nawawi:18', U&'D\2019apr\00e8s Abou Dharr Joundoub ibn Joun\00e2dah et Abou \2018Abd Ar-Rahm\00e2n Mou\2019\00e2dh ibn Jabal, qu\2019Allah les agr\00e9e, le Messager d\2019Allah \f072 a dit : \00ab Crains Allah o\00f9 que tu sois, fais suivre la mauvaise action par la bonne action, elle l\2019effacera, et comporte-toi avec ton prochain de la meilleure fa\00e7on. \00bb [At-Tirmidhi qui pr\00e9cise : \00ab hadith hasan \00bb ou, dans certains manuscrits \00ab hadith hasan sah\00eeh \00bb] Les calames sont lev\00e9s et l\2019encre a s\00e9ch\00e9'),
    (U&'nawawi:19', U&'Abou Al-\2018Abb\00e2s \2018Abdoullah ibn \2018Abb\00e2s \f074 relate ce qui suit : Alors que je me trouvais derri\00e8re le Proph\00e8te \f072 sur une monture, il me dit : \00ab Mon gar\00e7on ! Je vais te prodiguer certains enseignements : observe les prescriptions d\2019Allah, Il te prot\00e9gera, observe les prescriptions d\2019Allah, tu Le trouveras toujours avec toi. Si tu dois demander quelque chose, demande-le \00e0 Allah et si tu dois r\00e9clamer de l\2019aide, implore l\2019aide d\2019Allah. Et sache que si la nation enti\00e8re se rassemblait pour t\2019apporter un bienfait, elle ne t\2019apporterait que ce qu\2019Allah t\2019a pr\00e9destin\00e9. Et si elle se r\00e9unissait pour te causer un tort, elle te causerait uniquement le tort qu\2019Allah t\2019a pr\00e9destin\00e9. Les calames sont lev\00e9s et l\2019encre a s\00e9ch\00e9. \00bb [At-Tirmidhi qui pr\00e9cise : \00ab hadith hasan sah\00eeh \00bb] Selon une autre version que celle d\2019At-Tirmidhi, le Messager d\2019Allah \f072 a dit : \00ab Observe les prescriptions d\2019Allah, tu Le trouveras toujours avec toi. Souviens-toi d\2019Allah dans les moments faciles, Il se souviendra de toi dans les moments difficiles. Sache que ce qui ne t\2019a point atteint ne pouvait en aucun cas t\2019atteindre et que ce qui t\2019a atteint ne pouvait que t\2019atteindre. Et sache que la victoire s\2019obtient par la constance, que le soulagement vient apr\00e8s les souffrances et qu\2019il n\2019est pas d\2019\00e9preuve qui ne soit suivie d\2019une d\00e9livrance. \00bb La pudeur'),
    (U&'nawawi:20', U&'Selon Abou Mas\2019oud \2018Ouqbah ibn \2018Amr Al-Ans\00e2ri Al- Badri \f074, le Proph\00e8te \f072 a dit : \00ab Parmi les paroles h\00e9rit\00e9es des premiers proph\00e8tes figurent celles-ci : \201cSi tu n\2019\00e9prouves aucune pudeur, fais ce qu\2019il te pla\00eet\201d. \00bb [Al- Boukh\00e2ri] Suivre le droit chemin'),
    (U&'nawawi:21', U&'Soufy\00e2n ibn \2018Abdillah \f074 relate : J\2019ai dit : \00ab Messager d\2019Allah ! Enseigne-moi une parole au sujet de l\2019islam sur laquelle je n\2019interrogerai plus personne apr\00e8s toi. \00bb Le Proph\00e8te \f072 dit : \00ab Dis: \201cJe crois en Allah\201d, puis tiens-toi sur le droit chemin. \00bb [Mouslim] La voie du salut'),
    (U&'nawawi:22', U&'Selon Abou \2018Abdillah J\00e2bir ibn \2018Abdillah Al-Ans\00e2ri \f074, un homme interrogea le Messager d\2019Allah \f072 en ces termes : \00ab Si je me contente d\2019accomplir les pri\00e8res obligatoires et de je je\00fbner le mois de Ramadan, tout en accomplissant ce qui est licite6 et en fuyant ce qui est illicite, entrerai-je au Paradis. \00bb \00ab Oui \00bb, r\00e9pondit le Proph\00e8te \f072. [Mouslim] Tout homme vend son \00e2me'),
    (U&'nawawi:23', U&'D\2019apr\00e8s Abou M\00e2lik Al-H\00e2rith ibn \2018\00c2sim Al-Ach\2019ari \f074, le Messager d\2019Allah \f072 a dit : \00ab La purification repr\00e9sente la moiti\00e9 de la foi. Louer Allah remplit la Balance de bonnes actions, glorifier et louer Allah comble l\2019espace compris entre les cieux et la terre, la pri\00e8re est une lumi\00e8re, l\2019aum\00f4ne une preuve de foi, la patience est une clart\00e9 et le Coran un argument en ta faveur ou contre toi. Tous les hommes, en se levant le matin, vendent leur \00e2me : certains \00e0 Allah, la pr\00e9servant ainsi du ch\00e2timent, d\2019autres \00e0 Satan, provoquant ainsi leur perte. \00bb [Mouslim] Les faveurs insignes d\2019Allah'),
    (U&'nawawi:24', U&'Abou Dharr Al-Ghif\00e2ri \f074 rapporte ces paroles que le Proph\00e8te \f072 rapporte lui-m\00eame de son Seigneur \f055 : \00ab Mes 6 \00ab Accomplir ce qui est licite \00bb signifie ici, selon l\2019imam Nawawi lui- m\00eame : l\2019accomplir en \00e9tant convaincu que cela est licite. serviteurs ! Je Me suis interdit \00e0 Moi-m\00eame l\2019injustice et Je l\2019ai interdite entre vous, ne soyez donc pas injustes les uns envers les autres. Mes serviteurs ! Vous \00eates tous \00e9gar\00e9s, sauf celui que Je guide. Demandez-Moi donc de vous guider et Je vous guiderai. Mes serviteurs ! Vous \00eates tous affam\00e9s, sauf celui que Je nourris. Demandez-Moi donc de vous nourrir et Je vous nourrirai. Mes serviteurs ! Vous \00eates tous nus, sauf celui que Je v\00eatis. Demandez-Moi donc de vous v\00eatir et Je vous v\00eatirai. Mes serviteurs ! Vous p\00e9chez nuit et jour. Or, Je pardonne tous les p\00e9ch\00e9s. Demandez-Moi donc l\2019absolution et Je vous l\2019accorderai. Mes serviteurs ! Vous ne sauriez ni Me nuire, ni M\2019\00eatre utiles. Mes serviteurs ! Si du premier au dernier, hommes et djinns, vous aviez tous le c\0153ur du plus pieux d\2019entre vous, cela n\2019ajouterait rien \00e0 Mon royaume. Mes serviteurs ! Si du premier au dernier, hommes et djinns, vous aviez tous le c\0153ur du plus impie d\2019entre vous, cela n\2019enl\00e8verait rien \00e0 Mon royaume. Mes serviteurs ! Si du premier au dernier, hommes et djinns, vous vous teniez tous debout sur une m\00eame place en pri\00e8re et que J\2019exau\00e7ai chacun d\2019entre vous, cela ne r\00e9duirait de Mon royaume que ce qu\2019une aiguille plong\00e9e dans la mer peut r\00e9duire de sa quantit\00e9 d\2019eau. Mes serviteurs ! Seules importent vos \0153uvres dont Je tiens le compte pr\00e9cis et pour lesquelles Je vous r\00e9tribuerai pleinement. Que celui donc qui trouve un bien loue Allah et que celui qui trouve autre chose ne s\2019en prenne qu\2019\00e0 lui- m\00eame. \00bb [Mouslim] Toute bonne action est une aum\00f4ne'),
    (U&'nawawi:25', U&'D\2019apr\00e8s Abou Dharr \f074 toujours, certains de ses compagnons dirent au Proph\00e8te \f072 : \00ab Messager d\2019Allah ! Les riches ont accapar\00e9 les r\00e9compenses d\2019Allah. Ils prient et je\00fbnent comme nous, mais en plus ils font l\2019aum\00f4ne de l\2019exc\00e9dent de leurs richesses. \00bb Il r\00e9pondit : \00ab Allah ne vous a-t-Il pas donn\00e9 l\2019occasion de faire l\2019aum\00f4ne ? Ne savez- vous pas que dire : \201cGloire \00e0 Allah\201d est une aum\00f4ne, que dire : \201cAllah est plus grand que tout\201d est une aum\00f4ne, que dire : \201cLouange \00e0 Allah\201d est une aum\00f4ne, que dire : \201cIl n\2019y a de divinit\00e9 digne d\2019\00eatre ador\00e9e qu\2019Allah\201d est une aum\00f4ne, qu\2019inciter les autres \00e0 la vertu est une aum\00f4ne et que condamner le vice est une aum\00f4ne. M\00eame vos rapports conjugaux sont des aum\00f4nes. \00bb Les compagnons s\2019\00e9tonn\00e8rent : \00ab Messager d\2019Allah ! L\2019un de nous est-il r\00e9compens\00e9 pour un acte par lequel il assouvit simplement un d\00e9sir ? \00bb Il r\00e9pondit : \00ab Celui qui aurait eu des rapports ill\00e9gitimes n\2019aurait-il pas commis un p\00e9ch\00e9 ? Eh bien, de la m\00eame mani\00e8re, il est r\00e9compens\00e9 lorsqu\2019il a des rapports l\00e9gitimes. \00bb [Mouslim] Une aum\00f4ne pour chaque articulation'),
    (U&'nawawi:26', U&'D\2019apr\00e8s Abou Hourayrah \f074, le Messager d\2019Allah \f072 a dit : \00ab Chaque jour l\2019homme est redevable d\2019une aum\00f4ne pour chacune de ses articulations7 : juger ou r\00e9concilier \00e9quitablement deux personnes est une aum\00f4ne, aider un homme \00e0 s\2019installer sur sa monture ou lui tendre ses affaires une fois qu\2019il s\2019y est install\00e9 est une aum\00f4ne, toute bonne parole est une aum\00f4ne, chaque pas fait en direction de la mosqu\00e9e pour la pri\00e8re est une aum\00f4ne et retirer de la voie publique ce qui pourrait nuire aux passants est \00e9galement une aum\00f4ne. \00bb [Al- Boukh\00e2ri et Mouslim] Le vice et la vertu'),
    (U&'nawawi:27', U&'Selon An-Naww\00e2s ibn Sam\2019\00e2n \f074, le Proph\00e8te \f072 a dit : \00ab La vertu, c\2019est la noblesse de caract\00e8re et le vice, c\2019est ce qui te donne mauvaise conscience et que tu n\2019aimerais pas que les gens d\00e9couvrent. \00bb [Mouslim] Par ailleurs, W\00e2bisah ibn Ma\2019bad \f074 relate ce qui suit : J\2019allai un jour trouver le Messager d\2019Allah \f072 qui me demanda : \00ab Tu es venu m\2019interroger sur la vertu ? \00bb \00ab Oui \00bb, r\00e9pondis-je. Il dit : \00ab Interroge ton c\0153ur : la vertu est ce qui laisse ton 7 Selon un autre hadith rapport\00e9 par Mouslim, le corps humain est compos\00e9 de trois cent soixante articulations correspondant donc aux trois cent soixante jours de l\2019ann\00e9e. \00e2me et ton c\0153ur sereins, alors que le vice est ce qui te donne mauvaise conscience et qui cr\00e9e en toi un trouble, malgr\00e9 ce que les gens peuvent dire. \00bb [Hadith authentique (hasan), rapport\00e9 par Ahmad et Ad-D\00e2rimi dans leur Mousnad] S\2019attacher \00e0 la Sounnah'),
    (U&'nawawi:28', U&'Abou Naj\00eeh Al-\2018Irb\00e2d ibn S\00e2riyah \f074 relate ce qui suit : Le Messager d\2019Allah \f072 pronon\00e7a devant nous un sermon si \00e9loquent que nos c\0153urs en furent saisis de fr\00e9missement et que nos yeux en d\00e9bord\00e8rent de larmes. Nous d\00eemes : \00ab Messager d\2019Allah ! On dirait un sermon d\2019adieu, que nous recommandes-tu ? \00bb Il r\00e9pondit : \00ab Je vous recommande de craindre Allah et d\2019ob\00e9ir \00e0 vos dirigeants, m\00eame si c\2019est un esclave abyssin qui est \00e0 votre t\00eate. Celui parmi vous qui vivra verra en effet de nombreuses dissensions. Je vous recommande donc ma tradition et celle des califes orthodoxes bien guid\00e9s. Accrochez-vous-y fermement et m\00e9fiez-vous des nouveaut\00e9s introduites par certains dans la religion, car toute nouveaut\00e9 dans la religion est un \00e9garement. \00bb [Abou D\00e2woud et At-Tirmidhi, qui pr\00e9cise : \00ab hadith hasan sah\00eeh \00bb] Tenir sa langue'),
    (U&'nawawi:29', U&'Mou\2019\00e2dh ibn Jabal \f074 rapporte avoir demand\00e9 au Proph\00e8te \f072 : \00ab Messager d\2019Allah ! Indique-moi une \0153uvre qui me fasse entrer au Paradis et m\2019\00e9loigne de l\2019Enfer. \00bb Il r\00e9pondit : \00ab Tu m\2019as interrog\00e9 sur une chose capitale et ais\00e9e pour celui \00e0 qui Allah le Tr\00e8s Haut l\2019a rendue ais\00e9e : adore Allah sans rien Lui associer, accomplis la pri\00e8re, acquitte-toi de l\2019aum\00f4ne l\00e9gale, je\00fbne le mois de Ramadan et effectue le p\00e8lerinage au Sanctuaire de la Mecque. \00bb Puis il ajouta : \00ab Veux-tu conna\00eetre les portes du bien ? Le je\00fbne, car c\2019est une protection, l\2019aum\00f4ne, car elle efface les p\00e9ch\00e9s comme l\2019eau \00e9teint le feu, et les pri\00e8res au milieu de la nuit. \00bb Puis il r\00e9cita ces versets : \00ab Ils s\2019arrachent \00e0 leurs lits, prient leur Seigneur, remplis de crainte et d\2019espoir et offrent une partie de ce que Nous leur avons accord\00e9 par charit\00e9. Nul ne sait ce qui leur est r\00e9serv\00e9, en r\00e9compense de leurs \0153uvres, comme f\00e9licit\00e9. \00bb Puis il reprit : \00ab Veux-tu que je t\2019indique quelle est la chose la plus importante, ainsi que le pilier central et le sommet de celle-ci ? \00bb \00ab Oui, Messager d\2019Allah \00bb, r\00e9pondit-il. Il dit : \00ab La chose la plus importante est l\2019islam, son pilier, la pri\00e8re et son sommet, le combat pour la cause d\2019Allah. \00bb Il poursuivit : \00ab Veux-tu que je t\2019indique sur quoi repose tout ceci ? \00bb \00ab Oui, Messager d\2019Allah \00bb, r\00e9pondit-il. Il saisit alors sa langue et dit : \00ab Tiens celle-ci. \00bb Mou\2019\00e2dh demanda : \00ab Messager d\2019Allah ! Devrons-nous rendre compte de nos paroles ? \00bb Il r\00e9pondit : \00ab Les gens seront-ils jet\00e9s sur leurs visages en Enfer pour autre chose que ce qu\2019ils d\00e9bitent ? \00bb [At- Tirmidhi qui pr\00e9cise : \00ab hadith hasan sah\00eeh \00bb] Ne pas transgresser'),
    (U&'nawawi:30', U&'Selon Abou Tha\2019labah Al-Khouchani Jourthoum ibn N\00e2chir \f074, le Messager d\2019Allah \f072 a dit : \00ab Allah le Tr\00e8s Haut a impos\00e9 des obligations que vous ne devez pas n\00e9gliger, Il a fix\00e9 des limites que vous ne devez pas transgresser, et Il vous a soumis \00e0 des interdits que vous ne devez pas enfreindre. Il s\2019est par ailleurs tu sur certaines choses par mis\00e9ricorde pour vous, non par oubli, alors ne posez pas de questions \00e0 leur sujet. \00bb [Authentique (hasan), rapport\00e9 notamment par Ad-D\00e2raqoutni] L\2019amour d\2019Allah et des hommes'),
    (U&'nawawi:31', U&'Abou Al-\2018Abb\00e2s Sahl ibn Sa\2019d As-S\00e2\2019idi \f074 relate qu\2019un homme se rendit aupr\00e8s du Proph\00e8te \f072 et lui dit : \00ab Messager d\2019Allah ! Indique-moi un acte qui me vaudra l\2019amour d\2019Allah et celui des gens. \00bb Il r\00e9pondit : \00ab Renonce \00e0 ce monde, Allah t\2019aimera, et renonce \00e0 ce qui appartient aux gens, ceux-ci t\2019aimeront. \00bb [Hadith authentique (hasan), rapport\00e9 notamment par Ibn M\00e2jah] Ne faire de tort \00e0 personne'),
    (U&'nawawi:32', U&'Selon Abou Sa\2019\00eed Sa\2019d ibn Sin\00e2n Al-Khoudri \f074, le Messager d\2019Allah \f072 a dit : \00ab Ne faites de tort \00e0 personne, pas m\00eame \00e0 celui qui vous en a fait. \00bb [Hadith authentique (hasan), rapport\00e9 notamment par Ibn M\00e2jah et Ad- D\00e2raqoutni] La charge de la preuve'),
    (U&'nawawi:33', U&'D\2019apr\00e8s Ibn \2018Abb\00e2s \f074, le Messager d\2019Allah \f072 a dit : \00ab Si l\2019on jugeait en faveur des accusateurs sur la seule base de leurs d\00e9clarations, certains pr\00e9tendraient avoir des droits sur les biens ou le sang des autres. Mais la charge de la preuve incombe \00e0 l\2019accusateur, et le serment \00e0 celui qui nie. \00bb8 [Hadith authentique (hasan), rapport\00e9 notamment par Al-Bayhaqi en ces termes et par Al-Boukh\00e2ri et Mouslim en partie] R\00e9prouver le vice'),
    (U&'nawawi:34', U&'Abou Sa\2019\00eed Al-Khoudri \f074 rapporte avoir entendu le Messager d\2019Allah \f072 dire : \00ab Que celui d\2019entre vous qui voit un acte r\00e9pr\00e9hensible s\2019efforce d\2019y mettre un terme, s\2019il 8 A comparer aux articles 1353 et 2274 du code civil qui stipulent \00e9galement que la charge de la preuve incombe \00e0 l\2019accusateur. Voici l\2019article 2274 : \00ab La bonne foi est toujours pr\00e9sum\00e9e, et c\2019est \00e0 celui qui all\00e8gue la mauvaise foi \00e0 la prouver. \00bb ne le peut pas, alors qu\2019il le condamne par sa bouche, et s\2019il en est \00e9galement incapable, alors qu\2019il le r\00e9prouve dans son c\0153ur, et c\2019est l\00e0 le plus bas degr\00e9 de la foi. \00bb [Mouslim] La fraternit\00e9 en islam'),
    (U&'nawawi:35', U&'Selon Abou Hourayrah \f074, le Messager d\2019Allah \f072 a dit : \00ab Ne vous enviez pas les uns les autres, ne surench\00e9rissez pas frauduleusement9, ne vous ha\00efssez pas les uns les autres, ne vous fuyez pas les uns les autres et ne vous emparez pas injustement des clients des autres10, mais soyez au contraire, serviteurs d\2019Allah, tous fr\00e8res ! Le musulman est le fr\00e8re du musulman : il ne saurait le traiter injustement, lui montrer du m\00e9pris ou l\2019abandonner. La pi\00e9t\00e9 est ici - indiquant sa poitrine \00e0 trois reprises. Il suffit, pour commettre un p\00e9ch\00e9, de m\00e9priser son fr\00e8re musulman. Tout chez le musulman est sacr\00e9 pour les autres musulmans : son sang, ses biens et son honneur. \00bb [Mouslim] 9 Il s\2019agit de surench\00e9rir sans avoir l\2019intention d\2019acheter la marchandise, aux d\00e9pens des autres acheteurs et au profit du vendeur. 10 Apr\00e8s qu\2019un accord soit intervenu entre le vendeur et son ou ses clients. L\2019entraide'),
    (U&'nawawi:36', U&'D\2019apr\00e8s Abou Hourayrah \f074, le Proph\00e8te \f072 a dit : \00ab Celui qui soulage la peine d\2019un musulman ici-bas, Allah lui soulagera une peine le Jour de la r\00e9surrection. Celui qui aide une personne endett\00e9e, Allah l\2019aidera ici-bas et dans l\2019au-del\00e0. Celui qui couvre les d\00e9fauts et les p\00e9ch\00e9s d\2019un musulman, Allah couvrira les siens ici-bas et dans l\2019au- del\00e0. Allah soutient Son serviteur tant que celui-ci soutient son fr\00e8re musulman. A celui qui emprunte une voie en qu\00eate de savoir, Allah facilitera la voie menant au Paradis. Nul groupe de croyants ne se r\00e9unissent dans l\2019une des maisons d\2019Allah le Tr\00e8s Haut pour r\00e9citer le Livre d\2019Allah et l\2019\00e9tudier ensemble sans que la s\00e9r\00e9nit\00e9 ne descende sur eux, que la mis\00e9ricorde ne les couvre, que les anges ne les entourent, et qu\2019Allah ne les mentionne aux anges qui sont aupr\00e8s de Lui. Quant \00e0 celui que ses manquements auront \00e9loign\00e9 de son salut, il ne pourra s\2019en rapprocher par son lignage. \00bb [Mouslim] La r\00e9compense de la bonne action est d\00e9cupl\00e9e'),
    (U&'nawawi:37', U&'Ibn \2018Abb\00e2s \f074 rapporte ces paroles que le Messager d\2019Allah \f072 rapporte lui-m\00eame de son Seigneur, b\00e9ni et b\00e9ni soit-Il : \00ab Allah le Tr\00e8s Haut a inscrit les bonnes et les mauvaises actions \00bb, puis il expliqua : \00ab A celui qui a l\2019intention d\2019accomplir une bonne action, mais en est emp\00each\00e9, Allah, b\00e9ni et exalt\00e9 soit-Il, la lui inscrit aupr\00e8s de Lui comme une bonne action \00e0 part enti\00e8re. S\2019il l\2019accomplit, Allah la lui inscrit aupr\00e8s de Lui comme dix bonnes actions, et jusqu\2019\00e0 sept cents bonnes \0153uvres, et bien plus encore. S\2019il d\00e9cide de commettre une mauvaise action, mais y renonce finalement, Allah le Tr\00e8s Haut la lui inscrit aupr\00e8s de Lui comme une bonne action \00e0 part enti\00e8re. Et s\2019il la commet, Allah la lui inscrit comme une seule mauvaise action. \00bb [Al-Boukh\00e2ri et Mouslim] Comment obtenir l\2019amour d\2019Allah'),
    (U&'nawawi:38', U&'D\2019apr\00e8s Abou Hourayrah \f074, le Messager d\2019Allah \f072 a dit : \00ab Allah le Tr\00e8s Haut dit : \201cJe d\00e9clare la guerre \00e0 celui qui se fait l\2019ennemi de l\2019un de Mes pieux serviteurs. Mon adorateur ne se rapproche pas de Moi par des \0153uvres qui me sont plus ch\00e8res que celles que je lui ai impos\00e9es. Et Mon serviteur ne cesse de se rapprocher de moi par des \0153uvres volontaires jusqu\2019\00e0 ce que Je l\2019aime. Lorsque Je l\2019aime, je deviens son ou\00efe qui lui permet d\2019entendre, sa vue qui lui permet de voir, sa main qui lui permet de saisir et son pied qui lui permet de marcher. S\2019il Me sollicite, je r\00e9ponds \00e0 sa demande, et s\2019il implore Ma protection, Je la lui accorde\201d. \00bb [Al-Boukh\00e2ri] L\2019erreur, l\2019oubli et la contrainte'),
    (U&'nawawi:39', U&'D\2019apr\00e8s Ibn \2018Abb\00e2s \f074, le Messager d\2019Allah \f072 a dit : \00ab Par \00e9gard pour moi, Allah a pardonn\00e9 \00e0 ma nation tout acte commis par erreur, par oubli ou sous la contrainte. \00bb [Hadith authentique (hasan), rapport\00e9 notamment par Ibn M\00e2jah et Al-Bayhaqi] \00catre dans ce monde comme un voyageur'),
    (U&'nawawi:40', U&'Ibn \2018Oumar \f074 relate que le Messager d\2019Allah \f072 le prit un jour par l\2019\00e9paule et lui dit : \00ab Sois dans ce monde comme un \00e9tranger ou un voyageur de passage. \00bb Par ailleurs, Ibn \2018Oumar disait : \00ab Lorsque le soir arrive, n\2019attends pas d\2019\00eatre au matin et le matin n\2019attends pas d\2019\00eatre au soir. Profite de ta bonne sant\00e9 pour \0153uvrer avant d\2019en \00eatre emp\00each\00e9 par la maladie et profite de ta vie pour \0153uvrer avant d\2019\00eatre surpris par la mort. \00bb [Al-Boukh\00e2ri] Le vrai croyant'),
    (U&'nawawi:41', U&'D\2019apr\00e8s Abou Mouhammad \2018Abdoullah ibn \2018Amr ibn Al- \2018\00c2s \f074, le Messager d\2019Allah \f072 a dit : \00ab Vous ne serez vraiment croyant que lorsque vos passions se soumettront \00e0 mes enseignements. \00bb [Hadith authentique (hasan sah\00eeh)] L\2019infini pardon d\2019Allah'),
    (U&'nawawi:42', U&'Anas \f074 rapporte avoir entendu le Messager d\2019Allah \f072 dire : \00ab Allah le Tr\00e8s Haut dit : \201cFils d\2019Adam ! Tant que tu M\2019imploreras en esp\00e9rant Mon pardon, Je te pardonnerai, peu M\2019importent tes p\00e9ch\00e9s. Fils d\2019Adam ! Peu M\2019importe si tes p\00e9ch\00e9s atteignent le ciel, Je te pardonnerai, pour peu que tu implores Mon pardon. Fils d\2019Adam ! Si tu Me rencontrais avec le contenu de la terre comme p\00e9ch\00e9s, mais sans rien M\2019associer, Je t\2019accueillerais avec le contenu de la terre en pardon\201d. \00bb [At-Tirmidhi selon qui le hadith est authentique (hadith hasan)]')
) p(source_hadith_id,translation_text) join public.hadiths h on h.source_hadith_id=p.source_hadith_id and h.source_version_id='c2b5310f-3601-46c4-a2d8-3916895ba1d2' join public.hadith_collections c on c.id=h.collection_id and c.slug='nawawi' where t.hadith_id=h.id and t.source_version_id='c2b5310f-3601-46c4-a2d8-3916895ba1d2' and t.language_code='fr';

update public.hadith_source_versions set status='Disponible en production' where id='c2b5310f-3601-46c4-a2d8-3916895ba1d2';
update public.hadith_collections set lifecycle_status='Disponible en production' where slug='nawawi' and corpus_version='fawazahmed0-hadith-api@1:nawawi:ara+fra';
update public.hadith_books b set lifecycle_status='Disponible en production' where b.collection_id in(select id from public.hadith_collections where slug='nawawi' and corpus_version='fawazahmed0-hadith-api@1:nawawi:ara+fra');
update public.hadith_chapters ch set lifecycle_status='Disponible en production' where ch.book_id in(select b.id from public.hadith_books b join public.hadith_collections c on c.id=b.collection_id where c.slug='nawawi' and c.corpus_version='fawazahmed0-hadith-api@1:nawawi:ara+fra');
update public.hadiths h set lifecycle_status='Disponible en production' from public.hadith_collections c where h.collection_id=c.id and h.source_version_id='c2b5310f-3601-46c4-a2d8-3916895ba1d2' and h.source_hadith_id like 'nawawi:%' and c.slug='nawawi';
update public.hadith_translations t set lifecycle_status='Disponible en production' from public.hadiths h join public.hadith_collections c on c.id=h.collection_id where t.hadith_id=h.id and t.source_version_id='c2b5310f-3601-46c4-a2d8-3916895ba1d2' and t.language_code='fr' and h.source_version_id='c2b5310f-3601-46c4-a2d8-3916895ba1d2' and h.source_hadith_id like 'nawawi:%' and c.slug='nawawi';

do $$ declare n integer; begin select count(*) into n from public.hadith_published_translations where corpus_version='fawazahmed0-hadith-api@1:nawawi:ara+fra' and language_code='fr'; if n<>42 then raise exception 'Expected 42 published Nawawi translations, got %',n; end if; end $$;

commit;

select count(*) as published_nawawi_french_count from public.hadith_published_translations where corpus_version='fawazahmed0-hadith-api@1:nawawi:ara+fra' and language_code='fr';
